from pathlib import Path
import gzip, base64, sys
root=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path.cwd()
files={
'CMakeLists.txt':'',
'src/Common.cpp':'',
'src/StreamlineRuntime.cpp':'',
'src/StreamlineRuntime.h':'',
'tools/setup_streamline.ps1':'',
'FIX2-NOTES.txt':'',
}
for rel,data in files.items():
    p=root/rel; p.parent.mkdir(parents=True, exist_ok=True); p.write_bytes(gzip.decompress(base64.b64decode(data)))
    print('FIX2 wrote', rel, p.stat().st_size)
